34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "address_line1")
43	    private String addressLine1;
44	
45	    @Column(name = "address_line2")
46	    private String addressLine2;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
55	        message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    private String email;
60	
61	    @Column(name = "postcode")
62	    private String postcode;
63	
64	    @Column(name = "registration_date", columnDefinition = "DATE")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date", columnDefinition = "DATE")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "membership_number")
74	    private String membershipNumber;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "bulk_signup_warning")
86	    private Boolean bulkSignupWarning;
87	
88	    @Column(name = "possible_duplicate")
89	    private Boolean possibleDuplicate;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    public String getAddress() {
98	        return this.address;
99	    }
100	
101	    public void setAddress(String address) {
102	        this.address = address;
103	    }
104	
