110	        this.addressLine1 = addressLine1;
111	    }
112	
113	    public String getAddressLine2() {
114	        return this.addressLine2;
115	    }
116	
117	    public void setAddressLine2(String addressLine2) {
118	        this.addressLine2 = addressLine2;
