120	
121	    public String getCity() {
122	        return this.city;
123	    }
124	
125	    public void setCity(String city) {
126	        this.city = city;
127	    }
128	
129	    public String getTelephone() {
130	        return this.telephone;
131	    }
132	
133	    public void setTelephone(String telephone) {
134	        this.telephone = telephone;
135	    }
136	
137	    public String getEmail() {
138	        return this.email;
139	    }
140	
141	    public void setEmail(String email) {
142	        this.email = email;
