1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Create-time guard for {@code POST /owners}: rejects a request that is missing or blank in
12	 * any required field (firstName, lastName, address, city, telephone) with a 400 whose body
13	 * lists the offending field names. Runs first in the pipeline and publishes the body for
14	 * {@link BuildOwner} once it is known to be complete.
15	 *
16	 * <p>Distinct from {@link ValidateOwner} (the {@code @Valid} declarative path used by
17	 * {@code PUT /owners/{ownerId}}) for two reasons the spec forces here:
18	 * <ul>
19	 * <li>the create spec requires the {@code errors} array shape
20	 *     ({@link MissingOwnerFieldsException}), not the {@code ProblemDetail} a bean-validation
21	 *     escalation produces; and</li>
22	 * <li>"blank" must be rejected, which the DTO constraints do not express — {@code city} and
23	 *     {@code address} carry only {@code @NotNull @Size(min = 1)}, so a whitespace-only value
24	 *     passes bean validation. Hence the explicit {@link #isBlank(String)} check and the
25	 *     deliberate absence of {@code @Valid} on the binding.</li>
26	 * </ul>
27	 */
28	public class ValidateOwnerFields {
29	
30	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
31	            throws MissingOwnerFieldsException {
32	        List<String> missing = new ArrayList<>();
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
38	        }
39	        // Address may be supplied in a structured form (addressLine1 + optional addressLine2) or
40	        // as the flat 'address' (kept for backward compatibility). The structured form is preferred
41	        // whenever a non-blank addressLine1 is present; otherwise the flat address is used. Each
42	        // supplied field is normalised (trim/collapse/upper-case/expand abbreviations) and the
43	        // required-field check runs against that form, so a value blank only once normalised is
44	        // rejected. The canonical, composed value is written back onto 'address' in place, so it is
45	        // what gets stored and returned and what everything downstream reads — the household hash,
46	        // postcode validation and locality all see the structured-derived value, falling back to the
47	        // flat address when no structured fields were given.
48	        String normalizedLine1 = OwnerAddress.normalize(request.getAddressLine1());
49	        if (!normalizedLine1.isEmpty()) {
50	            String normalizedLine2 = OwnerAddress.normalize(request.getAddressLine2());
51	            request.setAddressLine1(normalizedLine1);
52	            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
53	            request.setAddress(OwnerAddress.compose(normalizedLine1, normalizedLine2));
54	        }
55	        else {
56	            String normalizedAddress = OwnerAddress.normalize(request.getAddress());
57	            if (normalizedAddress.isEmpty()) {
58	                missing.add("address");
59	            }
60	            else {
61	                request.setAddress(normalizedAddress);
62	            }
63	        }
64	        if (isBlank(request.getCity())) {
65	            missing.add("city");
66	        }
67	        if (isBlank(request.getTelephone())) {
68	            missing.add("telephone");
69	        }
70	        if (!missing.isEmpty()) {
71	            throw new MissingOwnerFieldsException(missing);
72	        }
73	        validated.set(request);
74	    }
75	
76	    private static boolean isBlank(String value) {
77	        return value == null || value.isBlank();
78	    }
79	}
